package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.sql.Statement;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The person store, kept per sheet. */
@Repository
public class People {

    private static final RowMapper<Person> ROW = (rs, i) -> {
        Person person = new Person(rs.getLong("id"),
                rs.getString("sheet_id"), rs.getString("name"), rs.getString("grade"), rs.getInt("version"));
        person.setStatementCount(rs.getInt("statement_count"));
        int terms = rs.getInt("terms");
        person.setTerms(rs.wasNull() ? null : terms);
        person.setContact(rs.getString("contact"));
        person.setStatedTotal(rs.getBigDecimal("stated_total"));
        java.sql.Date stated = rs.getDate("statement_date");
        person.setStatementDate(stated == null ? null : stated.toLocalDate());
        java.sql.Date retired = rs.getDate("retired_from");
        person.setRetiredFrom(retired == null ? null : retired.toLocalDate());
        java.sql.Date added = rs.getDate("added_on");
        person.setAddedOn(added == null ? null : added.toLocalDate());
        return person;
    };

    /** Patron names sorted without regard to case, then by case. */
    private static final java.util.Comparator<String> BY_NAME =
            String.CASE_INSENSITIVE_ORDER.thenComparing(java.util.Comparator.naturalOrder());

    private final JdbcTemplate jdbc;
    private final net.officefloor.hq.app.sheet.Sheets sheets;

    public People(JdbcTemplate jdbc, net.officefloor.hq.app.sheet.Sheets sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** Fills in each person's holds, in the order they were added. */
    private List<Person> withHolds(String sheetId, List<Person> found) {
        if (found.isEmpty()) {
            return found;
        }
        java.util.Map<Long, java.util.List<Person.Hold>> holds = new java.util.HashMap<>();
        jdbc.query("SELECT person_id, from_date, to_date FROM person_hold WHERE sheet_id = ? ORDER BY seq", rs -> {
            java.sql.Date to = rs.getDate("to_date");
            holds.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.ArrayList<>())
                    .add(new Person.Hold(rs.getDate("from_date").toLocalDate(), to == null ? null : to.toLocalDate()));
        }, sheetId);
        for (Person person : found) {
            person.setHolds(new java.util.ArrayList<>(holds.getOrDefault(person.getId(), List.of())));
        }
        return found;
    }

    /** Fills in each person's dated grades and the sheet's today (the grade in force on it is shown). */
    private List<Person> withGrades(String sheetId, List<Person> found) {
        if (found.isEmpty()) {
            return found;
        }
        java.time.LocalDate today = sheets.today(sheetId);
        java.util.Map<Long, java.util.Map<java.time.LocalDate, String>> grades = new java.util.HashMap<>();
        jdbc.query("SELECT person_id, from_date, grade FROM person_grade WHERE sheet_id = ? ORDER BY seq", rs -> {
            java.sql.Date from = rs.getDate("from_date");
            grades.computeIfAbsent(rs.getLong("person_id"), k -> new java.util.HashMap<>())
                    .put(from == null ? Person.BEGINNING : from.toLocalDate(), rs.getString("grade"));
        }, sheetId);
        withHolds(sheetId, found);
        for (Person person : found) {
            person.setGrades(grades.getOrDefault(person.getId(), java.util.Map.of()));
            person.setToday(today);
        }
        return found;
    }

    /** Writes the grade the person's edit recorded, replacing any recorded from the same date. */
    private void writeRecordedGrade(Person person) {
        java.util.Map.Entry<java.time.LocalDate, String> recorded = person.getRecordedGrade();
        if (recorded == null) {
            return;
        }
        java.sql.Date from = recorded.getKey().equals(Person.BEGINNING) ? null : java.sql.Date.valueOf(recorded.getKey());
        if (from == null) {
            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NULL",
                    person.getSheetId(), person.getId());
        } else {
            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date = ?",
                    person.getSheetId(), person.getId(), from);
        }
        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, from_date, grade) VALUES (?, ?, ?, ?)",
                person.getSheetId(), person.getId(), from, recorded.getValue());
        jdbc.update("INSERT INTO grade_history (sheet_id, person_id, set_on, from_date, grade) VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?)",
                person.getSheetId(), person.getId(), person.getSheetId(), from, recorded.getValue());
        person.clearRecordedGrade();
    }

    /** Records the person's name, own terms and contact as they now stand in their history, dated the sheet's today. */
    private void writeHistory(Person person) {
        jdbc.update("INSERT INTO person_history (sheet_id, person_id, set_on, name, terms, contact) VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?), ?, ?, ?)",
                person.getSheetId(), person.getId(), person.getSheetId(), person.getName(), person.getTerms(), person.getContact());
    }

    /** The sheet's people in the order they were added. */
    public List<Person> list(String sheetId) {
        return withGrades(sheetId, withPatrons(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? ORDER BY id", ROW, sheetId)));
    }

    /** Fills in each person's patrons (ids in the order named, names sorted). */
    private List<Person> withPatrons(String sheetId, List<Person> found) {
        if (found.isEmpty()) {
            return found;
        }
        java.util.Map<Long, java.util.List<Long>> ids = new java.util.HashMap<>();
        java.util.Map<Long, java.util.List<String>> names = new java.util.HashMap<>();
        jdbc.query("SELECT pp.person_id, pp.patron_id, p.name FROM person_patron pp"
                + " JOIN person p ON p.sheet_id = pp.sheet_id AND p.id = pp.patron_id"
                + " WHERE pp.sheet_id = ? ORDER BY pp.seq", rs -> {
                    long person = rs.getLong("person_id");
                    ids.computeIfAbsent(person, k -> new java.util.ArrayList<>()).add(rs.getLong("patron_id"));
                    names.computeIfAbsent(person, k -> new java.util.ArrayList<>()).add(rs.getString("name"));
                }, sheetId);
        for (Person person : found) {
            java.util.List<String> sorted = new java.util.ArrayList<>(names.getOrDefault(person.getId(), List.of()));
            sorted.sort(BY_NAME);
            person.setPatrons(new java.util.ArrayList<>(ids.getOrDefault(person.getId(), List.of())), sorted);
        }
        return found;
    }

    /** Records the patron as one of the person's patrons. The person's version is left as it is. */
    public void addPatron(Person person, Person patron) {
        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, set_on) VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                person.getSheetId(), person.getId(), patron.getId(), person.getSheetId());
        person.getPatronIds().add(patron.getId());
        person.getPatronNames().add(patron.getName());
        person.getPatronNames().sort(BY_NAME);
    }

    public Person find(String sheetId, long id) {
        List<Person> found = withGrades(sheetId, withPatrons(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND id = ?", ROW, sheetId, id)));
        return found.isEmpty() ? null : found.get(0);
    }

    /** The person on the sheet with this name, compared without regard to case or outer spaces; null when none. */
    public Person findByName(String sheetId, String name) {
        List<Person> found = withGrades(sheetId, jdbc.query("SELECT * FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?)) ORDER BY id",
                ROW, sheetId, name));
        return found.isEmpty() ? null : found.get(0);
    }

    /** Whether another person on the sheet already has this name, compared without regard to case. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND LOWER(TRIM(name)) = LOWER(TRIM(?))"
                        + (exceptId == null ? "" : " AND id <> " + exceptId.longValue()),
                Integer.class, sheetId, name);
        return count != null && count > 0;
    }

    /** Whether another person on the sheet already has this contact. */
    public boolean contactTaken(String sheetId, String contact, Long exceptId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND contact = ?"
                        + (exceptId == null ? "" : " AND id <> " + exceptId.longValue()),
                Integer.class, sheetId, contact);
        return count != null && count > 0;
    }

    public Person add(String sheetId, String name, String grade) {
        return add(sheetId, name, grade, null, null);
    }

    /** Adds a person with their own terms in days (null for none) and contact (null for none). */
    public Person add(String sheetId, String name, String grade, Integer terms, String contact) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade, terms, contact, added_on) VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setString(3, grade);
            ps.setObject(4, terms, java.sql.Types.INTEGER);
            ps.setString(5, contact);
            ps.setString(6, sheetId);
            return ps;
        }, keys);
        Person person = new Person(keys.getKey().longValue(), sheetId, name, grade);
        person.setTerms(terms);
        person.setContact(contact);
        writeHistory(person);
        // The first grade a person is given applies from the beginning of time.
        person.recordGrade(Person.BEGINNING, grade);
        writeRecordedGrade(person);
        person.setToday(sheets.today(sheetId));
        return person;
    }

    /** Records a statement taken for the person: one more, with its due-total and date. The person's
     *  version is left as it is — a statement is not an edit. */
    public void saveStatement(Person person) {
        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE sheet_id = ? AND id = ?",
                person.getStatementCount(), person.getStatedTotal(),
                person.getStatementDate() == null ? null : java.sql.Date.valueOf(person.getStatementDate()),
                person.getSheetId(), person.getId());
    }

    /** Records a statement taken for the person in their statement history. */
    public void addStatement(Person person) {
        jdbc.update("INSERT INTO person_statement (sheet_id, person_id, stated_total, statement_date, set_on) VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                person.getSheetId(), person.getId(), person.getStatedTotal(),
                person.getStatementDate() == null ? null : java.sql.Date.valueOf(person.getStatementDate()), person.getSheetId());
    }

    /** Marks the person's last statement cancelled in their history (kept, dated, for the as-of view) and sets the person's statement to the one
     *  before it (no due-total or date when there is none, or it is not known). The count goes down by one. */
    public void cancelStatement(Person person) {
        List<Long> last = jdbc.query("SELECT seq FROM person_statement WHERE sheet_id = ? AND person_id = ? AND NOT cancelled ORDER BY seq DESC LIMIT 1",
                (rs, i) -> rs.getLong(1), person.getSheetId(), person.getId());
        if (!last.isEmpty()) {
            jdbc.update("UPDATE person_statement SET cancelled = TRUE, cancelled_on = (SELECT today FROM sheet WHERE id = ?) WHERE seq = ?",
                    person.getSheetId(), last.get(0));
        }
        person.setStatementCount(person.getStatementCount() - 1);
        person.setStatedTotal(null);
        person.setStatementDate(null);
        jdbc.query("SELECT stated_total, statement_date FROM person_statement WHERE sheet_id = ? AND person_id = ? AND NOT cancelled ORDER BY seq DESC LIMIT 1",
                rs -> {
                    person.setStatedTotal(rs.getBigDecimal("stated_total"));
                    java.sql.Date date = rs.getDate("statement_date");
                    person.setStatementDate(date == null ? null : date.toLocalDate());
                }, person.getSheetId(), person.getId());
        saveStatement(person);
    }

    /** Records the person's retirement date. The person's version is left as it is — retiring is
     *  not an edit of the person form. */
    public void saveRetired(Person person) {
        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?",
                person.getRetiredFrom() == null ? null : java.sql.Date.valueOf(person.getRetiredFrom()),
                person.getSheetId(), person.getId());
        jdbc.update("INSERT INTO retire_history (sheet_id, person_id, set_on, retired_from) VALUES (?, ?, (SELECT today FROM sheet WHERE id = ?), ?)",
                person.getSheetId(), person.getId(), person.getSheetId(),
                person.getRetiredFrom() == null ? null : java.sql.Date.valueOf(person.getRetiredFrom()));
    }

    /** Adds a hold to the person. The person's version is left as it is — holding is not an edit of
     *  the person form. */
    public void addHold(Person person, Person.Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, set_on) VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                person.getSheetId(), person.getId(), java.sql.Date.valueOf(hold.from()),
                hold.to() == null ? null : java.sql.Date.valueOf(hold.to()), person.getSheetId());
        person.getHolds().add(hold);
    }

    /** Saves the person over the version it was loaded at, moving it on by one, with any grade the
     *  edit recorded; false (nothing written) when someone else has saved the person since. */
    public boolean save(Person person) {
        int updated = jdbc.update(
                "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
                person.getName(), person.getTerms(), person.getContact(), person.getSheetId(), person.getId(), person.getVersion());
        if (updated == 0) {
            return false;
        }
        writeRecordedGrade(person);
        writeHistory(person);
        person.setVersion(person.getVersion() + 1);
        return true;
    }
}
package net.officefloor.hq.app.person;

/** A person on a sheet. Mutable so an Apply step can change it in place. */
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

public class Person {

    /** The from-date standing for the beginning of time (stored as a null from-date). */
    public static final LocalDate BEGINNING = LocalDate.MIN;

    private final long id;
    private final String sheetId;
    private String name;
    /** The person's grades by the date each is in force from; {@link #BEGINNING} is the beginning of time. */
    private final java.util.TreeMap<LocalDate, String> grades = new java.util.TreeMap<>();
    /** The sheet's today when the person was loaded: the grade in force on it is the one shown. */
    private LocalDate today;
    /** A grade recorded by this edit and not yet written: its from-date and grade. */
    private java.util.Map.Entry<LocalDate, String> recorded;
    private int version;
    /** The person's own terms in days; null when they have none (their grade's or the sheet's apply). */
    private Integer terms;
    /** Whether this edit changed the person's terms from those loaded. */
    private boolean termsChanged;
    private int statementCount;
    private BigDecimal statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    /** The person's holds, in the order they were added. */
    private java.util.List<Hold> holds = new java.util.ArrayList<>();
    private java.util.List<Long> patronIds = new java.util.ArrayList<>();
    private java.util.List<String> patronNames = new java.util.ArrayList<>();

    public Person(long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(long id, String sheetId, String name, String grade, int version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grades.put(BEGINNING, grade);
        this.version = version;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    /** The grade in force on the sheet's today. */
    public String getGrade() { return gradeOn(today); }
    /** The grade in force on a date: the one with the latest from-date on or before it; with no date, the first. */
    public String gradeOn(LocalDate date) {
        java.util.Map.Entry<LocalDate, String> found = date == null ? null : grades.floorEntry(date);
        return found == null ? grades.firstEntry().getValue() : found.getValue();
    }
    /** The person's grades by from-date ({@link #BEGINNING} for the first), earliest first. */
    public java.util.SortedMap<LocalDate, String> getGrades() { return java.util.Collections.unmodifiableSortedMap(grades); }
    public void setGrades(java.util.Map<LocalDate, String> loaded) {
        if (!loaded.isEmpty()) {
            grades.clear();
            grades.putAll(loaded);
        }
    }
    /** Records the grade from the date (replacing one recorded from that same date), to be written on save. */
    public void recordGrade(LocalDate from, String grade) {
        grades.put(from, grade);
        recorded = java.util.Map.entry(from, grade);
    }
    /** The grade this edit recorded and has not written yet; null when none. */
    public java.util.Map.Entry<LocalDate, String> getRecordedGrade() { return recorded; }
    public void clearRecordedGrade() { recorded = null; }
    public LocalDate getToday() { return today; }
    public void setToday(LocalDate today) { this.today = today; }
    public int getVersion() { return version; }
    /** The person's own terms in days; null when none. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    /** Sets the terms the form gave, noting whether they differ from those the person had. */
    public void editTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }
    public boolean isTermsChanged() { return termsChanged; }
    /** The person's contact, trimmed and lower-cased; null when none. */
    private String contact;
    /** Whether this edit changed the person's contact from the one loaded. */
    private boolean contactChanged;
    public String getContact() { return contact; }
    public void setContact(String contact) { this.contact = contact; }
    /** Sets the contact the form gave, noting whether it differs from the one the person had. */
    public void editContact(String contact) {
        contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }
    public boolean isContactChanged() { return contactChanged; }
    /** How many statements have been taken for the person. */
    public int getStatementCount() { return statementCount; }
    /** The last statement's due-total; null when none was taken or it was n/a. */
    public BigDecimal getStatedTotal() { return statedTotal; }
    /** The sheet's today when the last statement was taken; null when none was. */
    public LocalDate getStatementDate() { return statementDate; }
    /** The date the person is retired from; null when not retired. Set means retired, whatever the date. */
    public LocalDate getRetiredFrom() { return retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    /** Whether a claim may be dated on this date: never after the person's retirement date. */
    public boolean allowsClaimOn(LocalDate date) { return retiredFrom == null || !date.isAfter(retiredFrom); }
    /** A hold from a date to an optional to-date (null: open-ended), both days included. */
    public record Hold(LocalDate from, LocalDate to) {
        public boolean covers(LocalDate date) {
            return date != null && !date.isBefore(from) && (to == null || !date.isAfter(to));
        }
    }
    /** Whether the person has any hold. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** The person's holds, in the order they were added. */
    public java.util.List<Hold> getHolds() { return holds; }
    public void setHolds(java.util.List<Hold> holds) { this.holds = holds; }
    /** Whether a hold of the person's covers the date. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.covers(date)); }
    /** Whether the claim counts in the live totals: OPEN, PENDING or SETTLED, but not OPEN or PENDING
     *  when dated within one of the person's holds, unless a statement binds it. */
    public boolean countsLive(Claim claim) {
        return claim.getStatus().counts()
                && !(claim.getStatus().isOpen() && !claim.isBound() && heldOn(claim.getDate()));
    }
    /** Whether the person's retirement date has been reached on the date (the sheet's today on or after it). */
    public boolean retiredOn(LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom);
    }
    /** Whether the claim counts in the live totals on the sheet's today: as {@link #countsLive(Claim)}, not deferred,
     *  and, once the person's retirement date is reached, not OPEN or PENDING unless a statement binds it. */
    public boolean countsLive(Claim claim, LocalDate today) {
        return countsLive(claim) && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isBound() && retiredOn(today));
    }
    /** Whether the claim counts in a period ending on the date: by the status it had at the end of that day (see
     *  {@link Claim#statusAt}), and, as in the live totals on the sheet's today, not deferred and not open, unbound and
     *  dated within one of the person's holds. */
    public boolean countsAtEnd(Claim claim, LocalDate end, LocalDate today) {
        ClaimStatus then = claim.statusAt(end);
        return then != null && then.counts() && !claim.isDeferredOn(today)
                && !(claim.getStatus().isOpen() && !claim.isBound() && heldOn(claim.getDate()));
    }
    /** The ids of the people the person has named as patrons, in the order they were named. */
    public java.util.List<Long> getPatronIds() { return patronIds; }
    /** The names of the person's patrons, sorted. */
    public java.util.List<String> getPatronNames() { return patronNames; }
    public void setPatrons(java.util.List<Long> ids, java.util.List<String> names) {
        this.patronIds = ids;
        this.patronNames = names;
    }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    public void setStatementCount(int statementCount) { this.statementCount = statementCount; }
    public void setStatedTotal(BigDecimal statedTotal) { this.statedTotal = statedTotal; }
    public void setStatementDate(LocalDate statementDate) { this.statementDate = statementDate; }
    public void setName(String name) { this.name = name; }
    /** The sheet's today when the person was added; null when not known. */
    private LocalDate addedOn;
    public LocalDate getAddedOn() { return addedOn; }
    public void setAddedOn(LocalDate addedOn) { this.addedOn = addedOn; }
    public void setVersion(int version) { this.version = version; }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** statementCount is how many statements were taken; statedTotal is the last one's due-total ("n/a" when it
 *  was n/a, "" when none was taken); statementDate is the sheet's today when it was taken ("" when none); retired says whether a retirement date is set and retiredFrom is it ("" when none); held says whether they have any hold and holds lists each (from, to; to "" when open-ended), in the order added; patrons are the names of the people they named as patrons, sorted, and patronIds their ids; grade is the grade in force on the sheet's today and grades every grade recorded, by from-date; terms is the person's own terms in days ("" for none); contact is the person's contact ("" for none). */
public record PersonResponse(String id, String name, String grade, int version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom, boolean held,
        List<HoldFrom> holds,
        List<String> patrons, List<String> patronIds, List<GradeFrom> grades, String terms, String contact) {

    /** A grade in force from a date (YYYY-MM-DD; "" for the beginning of time). */
    public record GradeFrom(String from, String grade) {
    }

    /** A hold from a date to a date (YYYY-MM-DD; to "" when open-ended). */
    public record HoldFrom(String from, String to) {
    }

    public static PersonResponse from(Person person) {
        boolean stated = person.getStatementCount() > 0;
        return new PersonResponse(String.valueOf(person.getId()), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                !stated ? "" : person.getStatedTotal() == null ? "n/a" : person.getStatedTotal().setScale(2).toPlainString(),
                person.getStatementDate() == null ? "" : person.getStatementDate().toString(),
                person.isRetired(), person.getRetiredFrom() == null ? "" : person.getRetiredFrom().toString(),
                person.isHeld(),
                person.getHolds().stream().map(h -> new HoldFrom(h.from().toString(), h.to() == null ? "" : h.to().toString())).toList(),
                List.copyOf(person.getPatronNames()),
                person.getPatronIds().stream().map(String::valueOf).toList(),
                person.getGrades().entrySet().stream().map(e -> new GradeFrom(
                        e.getKey().equals(Person.BEGINNING) ? "" : e.getKey().toString(), e.getValue())).toList(),
                person.getTerms() == null ? "" : String.valueOf(person.getTerms()),
                person.getContact() == null ? "" : person.getContact());
    }

    public static List<PersonResponse> from(List<Person> people) {
        return people.stream().map(PersonResponse::from).toList();
    }
}
