import org.springframework.web.bind.annotation.PathVariable;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;

public class ValidatePatron {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PatronRequest request, Out<PatronRequest> body, Settings settings)
            throws InvalidPersonException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        if (request.patronId() == null || request.patronId().isBlank()) {
            throw new InvalidPersonException("No patron chosen");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.person;

/** Body of POST /api/sheets/{sheetId}/people/{personId}/patrons: the id of the person named as patron, and who names them. */
public record PatronRequest(String patronId, String user) {
}
-- A person's patrons: other people on the same sheet they have named, each at most once, in the
-- order they were named (seq).
CREATE TABLE person_patron (
    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    patron_id BIGINT       NOT NULL,
    UNIQUE (sheet_id, person_id, patron_id)
);
-- A person's contact, trimmed and lower-cased; null for none. No two people on a sheet share one.
ALTER TABLE person ADD COLUMN contact VARCHAR(255);
-- Each contact recorded for a person, alongside their name and own terms.
ALTER TABLE person_history ADD COLUMN contact VARCHAR(255);

